#include <stdio.h>
/* ex04：索引分配——单级 / 两级 / 三级索引能支持多大文件
 * 单级：索引块全放块号  -> 最大 = 指针数 × 块大小
 * 两级：索引块指向索引块 -> 最大 = 指针数^2 × 块大小
 * 三级：再乘一次
 * 设块大小 4KB，块号 4 字节 -> 一个索引块可放 1024 个块号。*/
int main(void) {
    int blk = 4096, ptr = 4;
    int per_block = blk / ptr;      /* 每个索引块能放的块号数 */
    long long L1 = (long long)per_block * blk;
    long long L2 = (long long)per_block * per_block * blk;
    long long L3 = (long long)per_block * per_block * per_block * blk;

    printf("块大小=%dB 块号=%dB -> 一个索引块可放 %d 个块号\n", blk, ptr, per_block);
    printf("------------------------------------------------------------\n");
    printf("%-12s %-18s %-16s %s\n", "索引级数", "支持最大文件", "地址换算", "访问数据需读几个索引块");
    printf("%-12s %-18lld %-16s %d\n", "单级", L1, "1 次", 1);
    printf("%-12s %-18lld %-16s %d\n", "两级", L2, "2 次", 2);
    printf("%-12s %-18lld %-16s %d\n", "三级", L3, "3 次", 3);
    printf("------------------------------------------------------------\n");
    printf("单级 = %.1f MB，两级 = %.1f GB，三级 = %.1f TB\n",
           L1 / 1024.0 / 1024, L2 / 1024.0 / 1024 / 1024, L3 / 1024.0 / 1024 / 1024 / 1024);
    printf("结论: 索引分配支持随机访问且文件可增长，代价是「索引块本身要占空间且要多读几次」。\n");
    return 0;
}
